-- Cole tudo no SQL Editor e clique em Run. Pode rodar de novo sem problema.

-- libera a nova trilha 'pcba' nos registros de partidas
alter table public.partidas drop constraint if exists partidas_trilha_check;
alter table public.partidas add constraint partidas_trilha_check check (trilha in ('geral','pcba','policial','tribunais','fiscal','administrativa'));
alter table public.partidas_anonimas drop constraint if exists partidas_anonimas_trilha_check;
alter table public.partidas_anonimas add constraint partidas_anonimas_trilha_check check (trilha in ('geral','pcba','policial','tribunais','fiscal','administrativa'));

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":2939,"materia":"ml","nivel":1,"enunciado":"A rigidez cadavérica costuma começar pela:","opcoes":["Mandíbula e nuca","Ponta dos pés","Mãos","Região abdominal"],"explicacao":"Segue sentido craniocaudal (lei de Nysten)."},{"id":2940,"materia":"ml","nivel":1,"enunciado":"Os livores cadavéricos se formam nas regiões:","opcoes":["De declive do corpo","Mais altas do corpo","Somente no rosto","Ao redor das feridas"],"explicacao":"O sangue desce por gravidade."},{"id":2941,"materia":"ml","nivel":2,"enunciado":"Os livores cadavéricos se fixam, em regra, depois de cerca de:","opcoes":["12 horas","1 hora","3 dias","30 minutos"],"explicacao":"Antes disso, mudam de lugar se o corpo for virado."},{"id":2942,"materia":"ml","nivel":2,"enunciado":"A mancha verde abdominal, primeiro sinal da putrefação, surge em geral na fossa ilíaca:","opcoes":["Direita","Esquerda","Torácica","Lombar"],"explicacao":"Aparece em torno de 18 a 24 horas após a morte."},{"id":2943,"materia":"ml","nivel":1,"enunciado":"Cronotanatognose é:","opcoes":["A estimativa do tempo de morte","A identificação do cadáver","O estudo das asfixias mecânicas e químicas","A exumação"],"explicacao":"Usa fenômenos cadavéricos como rigidez, livores e temperatura."},{"id":2944,"materia":"ml","nivel":1,"enunciado":"Premoriência é:","opcoes":["A morte comprovada de uma pessoa antes de outra","A morte simultânea de várias pessoas num acidente","A morte encefálica","A morte presumida"],"explicacao":"Comoriência é quando não se sabe quem morreu primeiro."},{"id":2945,"materia":"ml","nivel":1,"enunciado":"Uma faca de ponta produz ferida:","opcoes":["Perfuroincisa","Contusa","Puntiforme","Incisa pura"],"explicacao":"Instrumento perfurocortante."},{"id":2946,"materia":"ml","nivel":1,"enunciado":"Uma navalha produz ferida:","opcoes":["Incisa","Contusa","Perfurocontusa","Lacerocontusa"],"explicacao":"Instrumento cortante."},{"id":2947,"materia":"ml","nivel":1,"enunciado":"O projétil de arma de fogo produz ferida:","opcoes":["Perfurocontusa","Incisa","Cortocontusa","Perfuroincisa"],"explicacao":"Instrumento perfurocontundente."},{"id":2948,"materia":"ml","nivel":2,"enunciado":"O machado e o facão produzem, em regra, ferida:","opcoes":["Cortocontusa","Puntiforme","Perfurocontusa","Incisa pura"],"explicacao":"Instrumentos cortocontundentes."},{"id":2949,"materia":"ml","nivel":1,"enunciado":"Prego e agulha produzem ferida:","opcoes":["Punctória (puntiforme)","Incisa","Cortocontusa","Contusa"],"explicacao":"Instrumentos perfurantes."},{"id":2950,"materia":"ml","nivel":2,"enunciado":"Em disparo a curta distância, além do orifício, a pele apresenta:","opcoes":["Zonas de tatuagem e de esfumaçamento","Só o orifício limpo","Apenas escoriação","Nenhum sinal"],"explicacao":"Resíduos da pólvora atingem a pele."},{"id":2951,"materia":"ml","nivel":2,"enunciado":"A orla de enxugo, no orifício de entrada do projétil, se forma pela:","opcoes":["Limpeza das impurezas do projétil na pele","Queima da pele pelos gases quentes da pólvora","Saída do projétil","Hemorragia interna"],"explicacao":"O projétil deixa sujeira na borda do orifício."},{"id":2952,"materia":"ml","nivel":1,"enunciado":"Em regra, o orifício de saída do projétil, comparado ao de entrada, é:","opcoes":["Maior, irregular e com bordas evertidas","Menor e com bordas invertidas","Igual ao de entrada, com zona de tatuagem ao redor","Sempre circular e regular"],"explicacao":"Na saída não há orlas de contusão e enxugo."},{"id":2953,"materia":"ml","nivel":2,"enunciado":"O sinal de Werkgaertner (desenho da boca do cano na pele) indica disparo:","opcoes":["Encostado","À longa distância","Acidental","De arma branca"],"explicacao":"A pele se queima com o formato do cano."},{"id":2954,"materia":"ml","nivel":2,"enunciado":"A câmara de mina de Hoffmann ocorre em disparo:","opcoes":["Encostado sobre plano ósseo, como o crânio","À longa distância","Com arma branca","Dentro da água"],"explicacao":"Os gases descolam o tecido e rompem a pele."},{"id":2955,"materia":"ml","nivel":1,"enunciado":"O enforcamento é a constrição do pescoço por laço acionado:","opcoes":["Pelo peso do próprio corpo","Pelas mãos de outra pessoa","Por outra força externa","Pela água"],"explicacao":"No estrangulamento, a força não é o peso do corpo."},{"id":2956,"materia":"ml","nivel":1,"enunciado":"A esganadura é a constrição do pescoço feita:","opcoes":["Com as mãos","Com laço e peso do corpo","Com laço apertado por força externa","Com líquido"],"explicacao":"Deixa marcas de unhas e dedos."},{"id":2957,"materia":"ml","nivel":2,"enunciado":"No enforcamento típico, o sulco no pescoço costuma ser:","opcoes":["Oblíquo e interrompido na altura do nó","Horizontal, contínuo e de profundidade uniforme","Sempre ausente","Em forma de dedos"],"explicacao":"No estrangulamento, o sulco é horizontal e contínuo."},{"id":2958,"materia":"ml","nivel":1,"enunciado":"O afogamento é asfixia por:","opcoes":["Entrada de líquido nas vias respiratórias","Constrição do pescoço","Compressão do tórax por peso ou soterramento","Ar rarefeito"],"explicacao":"É asfixia por modificação do meio."},{"id":2959,"materia":"ml","nivel":2,"enunciado":"Os critérios de morte encefálica no Brasil são definidos pelo:","opcoes":["Conselho Federal de Medicina","Ministério da Justiça e Segurança Pública","STF","Congresso Nacional"],"explicacao":"Resolução CFM 2.173/2017."},{"id":2960,"materia":"ml","nivel":1,"enunciado":"Exumação é:","opcoes":["Retirar o cadáver da sepultura para exame","Sepultar o corpo","Embalsamar o corpo para o velório","Cremar"],"explicacao":"Feita por determinação da autoridade."},{"id":2961,"materia":"ml","nivel":2,"enunciado":"Diferentemente do laudo, o auto médico-legal é:","opcoes":["Ditado pelo perito ao escrivão diante da autoridade","Redigido depois, só pelo perito, em seu gabinete","Um atestado médico comum","Uma certidão de óbito"],"explicacao":"O laudo é redigido pelo próprio perito."},{"id":2962,"materia":"ml","nivel":1,"enunciado":"O método de identificação baseado nos desenhos das pontas dos dedos é a:","opcoes":["Datiloscopia","Antropometria de Bertillon","Odontologia legal","Fotografia sinalética"],"explicacao":"É o principal método de identificação civil e criminal."},{"id":2963,"materia":"ml","nivel":2,"enunciado":"O sistema datiloscópico adotado no Brasil é o de:","opcoes":["Vucetich","Bertillon","Lombroso","Lacassagne"],"explicacao":"Juan Vucetich, criado na Argentina."},{"id":2964,"materia":"ml","nivel":2,"enunciado":"No sistema de Vucetich, os quatro tipos fundamentais são:","opcoes":["Arco, presilha interna, presilha externa e verticilo","Círculo, linha, ponto e espiral","Delta, núcleo, sulco, crista e linhas papilares","Alfa, beta, gama e delta"],"explicacao":"Representados por A, I, E e V nos polegares."},{"id":2965,"materia":"ml","nivel":1,"enunciado":"O que diferencia o infanticídio do homicídio é a mãe agir sob influência do:","opcoes":["Estado puerperal","Álcool","Medo da desonra perante a família","Pai da criança"],"explicacao":"Art. 123 do Código Penal."},{"id":2966,"materia":"ml","nivel":2,"enunciado":"A docimásia hidrostática de Galeno verifica se o recém-nascido:","opcoes":["Respirou, ou seja, nasceu com vida","Tinha alguma doença genética grave","Era prematuro","Foi envenenado"],"explicacao":"Pulmões que respiraram flutuam na água."},{"id":2967,"materia":"ml","nivel":1,"enunciado":"A queimadura de 2º grau se caracteriza por:","opcoes":["Bolhas (flictenas)","Só vermelhidão","Carbonização","Escara preta profunda"],"explicacao":"1º grau: eritema; 3º: escara; 4º: carbonização."},{"id":2968,"materia":"ml","nivel":2,"enunciado":"A marca elétrica de Jellinek é típica de lesão por:","opcoes":["Eletricidade industrial (eletroplessão)","Raio","Calor intenso do sol","Frio intenso"],"explicacao":"Raios causam fulguração ou fulminação."},{"id":2969,"materia":"ml","nivel":2,"enunciado":"As baropatias são lesões causadas por:","opcoes":["Variações da pressão atmosférica","Calor intenso do ambiente","Eletricidade","Ácidos"],"explicacao":"Ex.: doença descompressiva de mergulhadores."},{"id":2970,"materia":"ml","nivel":2,"enunciado":"No estupro de vulnerável, o vestígio de material biológico deve ser coletado respeitando a:","opcoes":["Cadeia de custódia","Ordem de chegada da vítima","Vontade do suspeito","Agenda do juiz"],"explicacao":"Arts. 158-A e seguintes do CPP."},{"id":2971,"materia":"igual","nivel":1,"enunciado":"Segundo o edital da PC-BA, a Lei 7.437/1985 (Lei Caó) incluiu entre as contravenções práticas resultantes de preconceito de:","opcoes":["Raça, cor, sexo ou estado civil","Renda, profissão ou nível de escolaridade","Religião apenas","Idade apenas"],"explicacao":"Ela alterou a antiga Lei Afonso Arinos."},{"id":2972,"materia":"igual","nivel":2,"enunciado":"Desde a Lei 14.532/2023, a injúria racial:","opcoes":["Foi equiparada ao racismo, sendo inafiançável e imprescritível","Continua sendo injúria simples do Código Penal, com pena menor","Virou contravenção","Deixou de ser crime"],"explicacao":"Passou para a Lei 7.716/1989."},{"id":2973,"materia":"igual","nivel":2,"enunciado":"Após 2023, a injúria racial está tipificada no:","opcoes":["Art. 2º-A da Lei 7.716/1989","Art. 140, § 3º, do Código Penal, apenas","Art. 147 do Código Penal","Art. 20 do Estatuto da Igualdade Racial"],"explicacao":"Pena de reclusão de 2 a 5 anos e multa."},{"id":2974,"materia":"igual","nivel":3,"enunciado":"Após 2023, o art. 140, § 3º, do Código Penal trata de injúria com elementos referentes a:","opcoes":["Religião ou condição de pessoa idosa ou com deficiência","Raça, cor, etnia e procedência nacional","Etnia","Procedência nacional"],"explicacao":"Raça, cor, etnia e procedência foram para a Lei 7.716/1989."},{"id":2975,"materia":"igual","nivel":1,"enunciado":"Pelo Estatuto da Igualdade Racial, ações afirmativas são:","opcoes":["Programas e medidas especiais para corrigir desigualdades raciais","Punições penais a quem pratica atos de racismo","Leis penais","Cotas só em empresas privadas"],"explicacao":"Art. 1º, parágrafo único, VI, da Lei 12.288/2010."},{"id":2976,"materia":"igual","nivel":1,"enunciado":"O Estatuto da Igualdade Racial garante às religiões de matriz africana:","opcoes":["Liberdade de consciência, de crença e de culto","Proibição de cultos públicos","Registro obrigatório dos templos na polícia","Isenção apenas de IPTU"],"explicacao":"Arts. 23 e 24 da Lei 12.288/2010."},{"id":2977,"materia":"igual","nivel":2,"enunciado":"A Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial foi promulgada pelo Decreto:","opcoes":["65.810/1969","4.377/2002","678/1992","4.886/2003"],"explicacao":"O 4.377/2002 promulgou a convenção sobre a mulher."},{"id":2978,"materia":"igual","nivel":2,"enunciado":"A Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher foi promulgada pelo Decreto:","opcoes":["4.377/2002","65.810/1969","678/1992","4.886/2003"],"explicacao":"Conhecida pela sigla CEDAW."},{"id":2979,"materia":"igual","nivel":2,"enunciado":"O Decreto 4.886/2003 instituiu a:","opcoes":["Política Nacional de Promoção da Igualdade Racial","Lei Maria da Penha","Secretaria Nacional de Direitos Humanos","Lei de Cotas"],"explicacao":"Política coordenada pelo governo federal."},{"id":2980,"materia":"igual","nivel":2,"enunciado":"A Lei 10.678/2003 criou a:","opcoes":["Secretaria Especial de Políticas de Promoção da Igualdade Racial","Lei Caó","Lei de Cotas","Fundação Cultural Palmares"],"explicacao":"A Seppir, ligada à Presidência."},{"id":2981,"materia":"igual","nivel":2,"enunciado":"A Lei 14.600/2023, que organizou os ministérios, inclui o Ministério:","opcoes":["Da Igualdade Racial","Do Petróleo","Da Defesa Civil","Dos Esportes Radicais"],"explicacao":"Também o das Mulheres e o dos Povos Indígenas."},{"id":2982,"materia":"igual","nivel":1,"enunciado":"Pela Lei 7.716/1989, impedir alguém de entrar em estabelecimento comercial por causa da raça é:","opcoes":["Crime","Mera infração civil","Contravenção","Fato atípico"],"explicacao":"Crime resultante de preconceito."},{"id":2983,"materia":"igual","nivel":1,"enunciado":"Os crimes da Lei 7.716/1989 são punidos com:","opcoes":["Reclusão","Detenção","Prisão simples","Somente multa"],"explicacao":"Também são inafiançáveis e imprescritíveis."},{"id":2984,"materia":"igual","nivel":2,"enunciado":"Pela Lei 7.716/1989, praticar discriminação por meio de comunicação social ou redes tem pena de:","opcoes":["Reclusão de 2 a 5 anos e multa","Reclusão de 1 a 3 anos, sem aumento","Somente multa","Detenção de 1 mês"],"explicacao":"Art. 20, § 2º."},{"id":2985,"materia":"igual","nivel":2,"enunciado":"Pela Lei 2.889/1956, a pena do genocídio aumenta se o crime é cometido por:","opcoes":["Governante ou funcionário público","Pessoa com mais de 60 anos","Estrangeiro","Estudante"],"explicacao":"Aumento de 1/3 (art. 4º)."},{"id":2986,"materia":"igual","nivel":1,"enunciado":"O genocídio busca destruir, no todo ou em parte, grupo:","opcoes":["Nacional, étnico, racial ou religioso","Político, partidário ou ideológico","Profissional","Esportivo"],"explicacao":"Art. 1º da Lei 2.889/1956."},{"id":2987,"materia":"igual","nivel":2,"enunciado":"Pela CEDAW, a discriminação contra a mulher é a distinção baseada no sexo que prejudica:","opcoes":["O exercício dos direitos humanos da mulher","Só o direito ao voto e de ser votada","Só o trabalho","Só o casamento"],"explicacao":"Art. 1º da Convenção."},{"id":2988,"materia":"igual","nivel":1,"enunciado":"Pela Lei Maria da Penha, a violência moral é:","opcoes":["Calúnia, difamação ou injúria","Agressão física com marcas visíveis","Retenção de bens","Coação sexual"],"explicacao":"Art. 7º, V."},{"id":2989,"materia":"igual","nivel":2,"enunciado":"Pela Lei Maria da Penha, a violência sexual inclui:","opcoes":["Impedir o uso de método contraceptivo","Xingar a vítima em público","Reter documentos","Dar socos"],"explicacao":"Art. 7º, III."},{"id":2990,"materia":"igual","nivel":1,"enunciado":"Pela Constituição, é objetivo da República promover o bem de todos, sem preconceitos de:","opcoes":["Origem, raça, sexo, cor, idade e outras formas de discriminação","Apenas religião","Apenas renda","Apenas nacionalidade estrangeira"],"explicacao":"Art. 3º, IV."},{"id":2991,"materia":"igual","nivel":1,"enunciado":"Nas relações internacionais, o Brasil se rege, entre outros, pelo repúdio ao:","opcoes":["Terrorismo e ao racismo","Comércio exterior com países vizinhos","Turismo","Capital estrangeiro"],"explicacao":"Art. 4º, VIII."},{"id":2992,"materia":"igual","nivel":2,"enunciado":"Na Constituição da Bahia, o capítulo “Do Negro” é o capítulo:","opcoes":["XXIII","V","X","I"],"explicacao":"Conforme o conteúdo programático do edital da PC-BA."},{"id":2993,"materia":"igual","nivel":2,"enunciado":"A Lei Estadual 13.182/2014 instituiu na Bahia o:","opcoes":["Estatuto da Igualdade Racial e de Combate à Intolerância Religiosa","Código de Trânsito estadual da Bahia","Estatuto do Servidor","Plano Diretor de Salvador"],"explicacao":"Conforme o edital da PC-BA."},{"id":2994,"materia":"ml","nivel":1,"enunciado":"O esfriamento do cadáver (algor mortis) é um fenômeno cadavérico:","opcoes":["Abiótico consecutivo","Transformativo destrutivo","Conservador","Vital"],"explicacao":"Assim como a rigidez e os livores."},{"id":2995,"materia":"ml","nivel":2,"enunciado":"A maceração é fenômeno cadavérico típico de:","opcoes":["Fetos mortos no útero e corpos em meio líquido","Corpos em locais muito secos e quentes","Corpos congelados","Cadáveres embalsamados"],"explicacao":"É um fenômeno transformativo destrutivo."},{"id":2996,"materia":"ml","nivel":2,"enunciado":"A mumificação natural ocorre, em regra, em ambiente:","opcoes":["Quente, seco e arejado","Úmido, frio e sem circulação de ar","Submerso","Fechado e úmido"],"explicacao":"É um fenômeno conservador."},{"id":2997,"materia":"ml","nivel":2,"enunciado":"A saponificação (adipocera) ocorre em ambiente:","opcoes":["Úmido e pouco arejado","Seco, quente e muito ventilado","Muito ventilado","Congelado"],"explicacao":"A gordura do corpo vira uma substância parecida com sabão."},{"id":2998,"materia":"ml","nivel":1,"enunciado":"Quanto à causa jurídica, a morte pode ser:","opcoes":["Natural, acidental, suicida ou homicida","Rápida, lenta ou agônica, conforme a duração","Diurna ou noturna","Urbana ou rural"],"explicacao":"A causa médica é outra classificação."},{"id":2999,"materia":"ml","nivel":1,"enunciado":"A lesão contusa em que pequenos vasos se rompem sob a pele, deixando mancha, é a:","opcoes":["Equimose","Escoriação","Ferida incisa","Fratura"],"explicacao":"O popular “roxo”."},{"id":3000,"materia":"ml","nivel":1,"enunciado":"A escoriação é a lesão que atinge:","opcoes":["A epiderme, arrancando a camada superficial","O osso","Somente os músculos mais profundos","Os órgãos internos"],"explicacao":"O popular “ralado”."},{"id":3001,"materia":"ml","nivel":2,"enunciado":"O espectro das cores da equimose ajuda a estimar:","opcoes":["A idade aproximada da lesão","O tipo sanguíneo","A arma usada","O sexo e a altura do agressor"],"explicacao":"Do vermelho-violáceo ao amarelo, com o passar dos dias."},{"id":3002,"materia":"leg","nivel":1,"enunciado":"Pela Lei 5.553/1968, reter documento de identificação de outra pessoa é:","opcoes":["Contravenção penal","Crime hediondo","Permitido por até 30 dias","Infração de trânsito"],"explicacao":"Art. 3º da Lei 5.553/1968."},{"id":3003,"materia":"leg","nivel":2,"enunciado":"Pela Lei 5.553/1968, para entrar num prédio, quem exige o documento deve:","opcoes":["Anotar os dados no ato e devolver o documento imediatamente","Reter o documento até a saída do visitante, devolvendo na portaria","Fotocopiar e ficar com o original","Recusar a entrada de quem não deixar o documento"],"explicacao":"Art. 2º, § 2º, da Lei 5.553/1968."},{"id":3004,"materia":"leg","nivel":1,"enunciado":"Pela Lei 12.037/2009, o civilmente identificado, em regra:","opcoes":["Não será submetido à identificação criminal","Sempre ser